 6	var API = (function () {
 7	  async function request(method, path, body) {
 8	    var opts = {
 9	      method: method,
10	      headers: {},
11	    };
12	    if (body !== undefined) {
13	      opts.headers['Content-Type'] = 'application/json';
14	      opts.body = JSON.stringify(body);
15	    }
16	    var res = await fetch('/api' + path, opts);
17	    if (!res.ok) {
18	      var errData = null;
19	      try { errData = await res.json(); } catch (_) {}
20	      var errMsg = (errData && errData.error && errData.error.message) || ('HTTP ' + res.status);
21	      var errCode = (errData && errData.error && errData.error.code) || 'ERROR';
22	      throw { code: errCode, message: errMsg };
23	    }
24	    if (res.status === 204) return null;
25	    return res.json();
26	  }
27	
28	  /**
29	   * Serialize *params* as a URL query string.
30	   *
31	   * Keys whose value is `undefined` or an empty string (`''`) are silently
32	   * omitted from the output.  This is intentional: callers use `undefined` as
33	   * a "no filter" sentinel (e.g. `{ wp: wpId }` where `wpId` may be
34	   * `undefined`), and the omission prevents `?wp=undefined` from reaching
35	   * the server.
36	   *
37	   * @param {Record<string, any>|null|undefined} params - Key/value pairs to encode.
38	   * @returns {string} A `?key=value&…` string, or `''` when no params survive
39	   *   the filter.
40	   */
41	  function buildQueryString(params) {
42	    if (!params) return '';
43	    var parts = Object.keys(params)
44	      .filter(function (k) { return params[k] !== undefined && params[k] !== ''; })
45	      .map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); });
46	    return parts.length ? '?' + parts.join('&') : '';
47	  }
48	
49	  return {
50	    /**

  1	/* ============================================================
  2	   views/project-detail-dialogues.js — Project Detail: Dialogues section
  3	   Sub-module of views/project-detail.js.
  4	   Depends on: components.js (UI), utils.js (escapeHtml),
  5	               api-client.js (API)
  6	               This script must be loaded after project-detail-orch.js
  7	               and before project-detail.js in index.html.
  8	
  9	   Exports:
 10	     buildDialogueHTML
 11	     renderDialoguesSection
 12	   ============================================================ */
 13	
 14	/* ----------------------------------------------------------
 15	   Interactive dialogue renderer (WP-006)
 16	   ---------------------------------------------------------- */
 17	
 18	/**
 19	 * Render inline Markdown (bold, italic, inline code) in a plain-text string.
 20	 * Delegates to marked.parseInline() when available; falls back to safe regex
 21	 * substitution (HTML-escaped first) so XSS is impossible on both code paths.
 22	 *
 23	 * @param {string} text - Raw text that may contain **bold**, *italic*, `code`.
 24	 * @returns {string} Safe HTML string.
 25	 */
 26	function _dialogueInlineMarkdown(text) {
 27	  if (typeof marked !== 'undefined' && typeof marked.parseInline === 'function') {
 28	    // Pre-escape HTML before passing to marked so any raw HTML in the input is
 29	    // neutralised before marked processes it. Markdown syntax characters
 30	    // (* _ ` \n) are unaffected by escapeHtml, so bold/italic/code still render
 31	    // correctly. This makes the primary path consistent with the regex fallback.
 32	    return marked.parseInline(escapeHtml(text));
 33	  }
 34	  // Regex fallback: escape HTML first, then apply simple Markdown transforms.
 35	  var safe = escapeHtml(text);
 36	  safe = safe.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
 37	  safe = safe.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');
 38	  safe = safe.replace(/`([^`\n]+)`/g, '<code>$1</code>');
 39	  return safe;
 40	}
 41	
 42	/**
 43	 * Build HTML for a 'text' dialogue block.
 44	 * Splits content on double newlines to form individual paragraph elements.
 45	 *
 46	 * @param {{type: 'text', content: string}} block
 47	 * @returns {string} HTML string
 48	 */
 49	function _buildDialogueTextBlock(block) {
 50	  var content = block.content || '';
 51	  var paragraphs = content.split(/\n\n+/);
 52	  var pHtml = '';
 53	  var i, para;
 54	  for (i = 0; i < paragraphs.length; i++) {
 55	    para = paragraphs[i].trim();
 56	    if (!para) continue;
 57	    pHtml += '<p>' + _dialogueInlineMarkdown(para) + '</p>';
 58	  }
 59	  return '<div class="dialogue-text">' + pHtml + '</div>';
 60	}
 61	
 62	/**
 63	 * Build HTML for a 'tool-call' dialogue block.
 64	 * Renders as a collapsed-by-default card: toggle button (always visible),
 65	 * ↳ detail lines (always visible, between button and body), and a
 66	 * collapsible body containing the args JSON and optional tool result.
 67	 *
 68	 * @param {{type: 'tool-call', name: string, detailLines: string[], args: *, result: {content: string}|undefined}} block
 69	 * @returns {string} HTML string
 70	 */
 71	function _buildDialogueToolCallBlock(block) {
 72	  var name = block.name || 'unknown';
 73	  var detailLines = block.detailLines || [];
 74	  var args = block.args;
 75	  var result = block.result;
 76	  var i;
 77	
 78	  // Toggle button — always visible, collapsed by default.
 79	  var headerHtml =
 80	    '<button class="dialogue-tool-toggle" aria-expanded="false">' +
 81	      '<span class="dialogue-tool-arrow">\u25b6</span>' +
 82	      'Tool call: ' + escapeHtml(name) +
 83	    '</button>';
 84	
 85	  // ↳ detail lines — always visible, outside the hidden body.
 86	  var detailHtml = '';
 87	  if (detailLines.length) {
 88	    detailHtml += '<div class="dialogue-tool-detail-area">';
 89	    for (i = 0; i < detailLines.length; i++) {
 90	      detailHtml += '<div class="dialogue-tool-detail-line">' + escapeHtml(detailLines[i]) + '</div>';
 91	    }
 92	    detailHtml += '</div>';
 93	  }
 94	
 95	  // Collapsible body: args JSON + optional result (hidden by default).
 96	  var argsJson;
 97	  try {
 98	    argsJson = JSON.stringify(args, null, 2);
 99	  } catch (e) {
100	    argsJson = String(args);

101	  }
102	
103	  var bodyHtml = '<pre class="dialogue-tool-args">' + escapeHtml(argsJson) + '</pre>';
104	
105	  if (result && result.content) {
106	    bodyHtml +=
107	      '<div class="dialogue-tool-result">' +
108	        '<span class="dialogue-tool-result-label">Result:</span>' +
109	        escapeHtml(result.content) +
110	      '</div>';
111	  }
112	
113	  return '<div class="dialogue-tool-call">' +
114	    headerHtml +
115	    detailHtml +
116	    '<div class="dialogue-tool-details" hidden>' + bodyHtml + '</div>' +
117	  '</div>';
118	}
119	
120	/**
121	 * Build HTML for a 'checklist' dialogue block (write_todos invocation).
122	 *
123	 * @param {{type: 'checklist', items: Array<{content: string, status: string, checked: boolean}>}} block
124	 * @returns {string} HTML string
125	 */
126	function _buildDialogueChecklistBlock(block) {
127	  var items = block.items || [];
128	  var listHtml = '';
129	  var i, item, isChecked, checkedAttr, checkedClass;
130	  for (i = 0; i < items.length; i++) {
131	    item = items[i];
132	    isChecked = !!item.checked;
133	    checkedAttr  = isChecked ? ' checked' : '';
134	    checkedClass = isChecked ? ' class="checked"' : '';
135	    listHtml +=
136	      '<li' + checkedClass + '>' +
137	        '<input type="checkbox" disabled' + checkedAttr + '>' +
138	        '<span>' + escapeHtml(item.content || '') + '</span>' +
139	      '</li>';
140	  }
141	  return '<div class="dialogue-checklist"><ul>' + listHtml + '</ul></div>';
142	}
143	
144	/**
145	 * Build HTML for a 'subagent-heading' dialogue block.
146	 *
147	 * @param {{type: 'subagent-heading', label: string}} block
148	 * @returns {string} HTML string
149	 */
150	function _buildDialogueSubagentHeadingBlock(block) {
151	  return '<h3 class="dialogue-subagent-heading">' + escapeHtml(block.label || '') + '</h3>';
152	}
153	
154	/**
155	 * Transform an array of DialogueBlocks into interactive HTML.
156	 *
157	 * - 'text'             → clean paragraphs with inline Markdown support
158	 * - 'tool-call'        → collapsed-by-default card with args/result toggle
159	 * - 'checklist'        → styled list with checkbox indicators
160	 * - 'subagent-heading' → <h3> element
161	 *
162	 * All string values are passed through escapeHtml() for XSS defence.
163	 * All JavaScript follows ES5 patterns (var, function declarations, .then() chains).
164	 *
165	 * @param {Array<{type: string}>} blocks - Array of DialogueBlock objects.
166	 * @returns {string} Safe HTML string ready for assignment to .innerHTML.
167	 */
168	function buildDialogueHTML(blocks) {
169	  if (!blocks || !blocks.length) {
170	    return '<p class="text-muted">No dialogue content.</p>';
171	  }
172	  var html = '';
173	  var i, block;
174	  for (i = 0; i < blocks.length; i++) {
175	    block = blocks[i];
176	    if (block.type === 'text') {
177	      html += _buildDialogueTextBlock(block);
178	    } else if (block.type === 'tool-call') {
179	      html += _buildDialogueToolCallBlock(block);
180	    } else if (block.type === 'checklist') {
181	      html += _buildDialogueChecklistBlock(block);
182	    } else if (block.type === 'subagent-heading') {
183	      html += _buildDialogueSubagentHeadingBlock(block);
184	    }
185	  }
186	  return '<div class="dialogue-interactive">' + html + '</div>';
187	}
